export function formatPrice(amount) {
  return new Intl.NumberFormat("es-CR", {
    style: "currency",
    currency: "CRC",
  }).format(amount);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { formatPrice } from "../src/format.mjs";

test("formatPrice formatea números como moneda CRC", () => {
  const result = formatPrice(2500);
  // Verificamos que contenga el símbolo de Colón y los dígitos
  assert.ok(result.includes("₡"));
  assert.ok(result.includes("2"));
  assert.ok(result.includes("500"));
  assert.ok(result.includes(",00"));
});

test("formatPrice maneja decimales", () => {
  const result = formatPrice(123.45);
  assert.ok(result.includes("123,45"));
});

